    #[cfg(feature = "dbus-compat")]
    info!("Compatibility: D-Bus org.freedesktop.WireGuardAuth1");

    // Wait for shutdown
    select! {
        _ = tokio::signal::ctrl_c() => {
            info!("Shutting down...");
        }
        result = jsonrpc_task => {
            warn!("JSON-RPC server stopped: {:?}", result);
        }
        #[cfg(feature = "dbus-compat")]
