  /* Scroll chat to bottom on new messages */
  const scrollToBottom = useCallback(() => {
    threadRef.current?.scrollTo({
      top: threadRef.current.scrollHeight,
      behavior: "smooth",
    });
  }, []);
  useEffect(() => {
    scrollToBottom();
  }, [messages, scrollToBottom]);

  /* Bind the Session Sled from Ghostbridge headers */
  useEffect(() => {
    const traceId = sessionStorage.getItem("X-Ghostbridge-Trace-ID") || "";
    const footprint = sessionStorage.getItem("X-Ghostbridge-Footprint") || "";
    if (traceId || footprint) {
      setActiveSled({ traceId, footprint, mutationIndex: 0 });
    }
  }, []);

  /* ── Chat send handler (stub — will bind to gRPC-Web stream) ── */
  const handleSend = () => {
    if (!draft.trim() || !connected) return;
    const userMsg: ChatMessage = {
      id: `msg-${Date.now()}`,
      role: "user",
      content: draft.trim(),
      timestamp: Date.now(),
    };
    setMessages((prev) => [...prev, userMsg]);
    setDraft("");
    setSending(true);

    // Stub: simulates gRPC-Web round-trip from op-grpc-bridge
    setTimeout(() => {
      const assistantMsg: ChatMessage = {
        id: `msg-${Date.now()}-resp`,
        role: "assistant",
        content: `Acknowledged "${userMsg.content}". Compliance trace appended to Snowball.`,
        timestamp: Date.now(),
      };
      setMessages((prev) => [...prev, assistantMsg]);
      setSending(false);
      setActiveSled((prev) =>
        prev ? { ...prev, mutationIndex: prev.mutationIndex + 1 } : prev,
      );
    }, 600);
  };

  const handleKeyDown = (e: React.KeyboardEvent) => {
    if (e.key === "Enter" && !e.shiftKey) {
      e.preventDefault();
      handleSend();
    }
  };

  /* ── Qdrant semantic trace refresh ── */
  const handleTraceSearch = useCallback(async () => {
    setTraceLoading(true);
